def transform2(grid, trace=False):
    h=len(grid); w=len(grid[0])
    out=[row[:] for row in grid]
    used=[[False]*w for _ in range(h)]
    def val(r,c):
        return 0<=r<h and 0<=c<w and grid[r][c]==8 and not used[r][c]
    colmap={(0,0):2,(1,0):3,(0,1):4,(1,1):5}
    for r in range(h):
        for c in range(w):
            if grid[r][c]!=8 or used[r][c]: continue
            if val(r,c+1) and val(r+1,c) and val(r+1,c+1):
                if trace: print('2x2 at',(r,c))
                cells=[(r,c),(r,c+1),(r+1,c),(r+1,c+1)]
                for rr,cc in cells: used[rr][cc]=True; out[rr][cc]=1
                continue
            done=False
            for (r0,c0) in [(r,c),(r,c-1),(r-1,c),(r-1,c-1)]:
                if r0<0 or c0<0 or r0+1>=h or c0+1>=w: continue
                cells=[(rr,cc) for rr in (r0,r0+1) for cc in (c0,c0+1) if val(rr,cc)]
                if len(cells)==3 and (r,c) in cells and min(cells)==(r,c):
                    mr,mc=[(rr,cc) for rr in (r0,r0+1) for cc in (c0,c0+1) if (rr,cc) not in cells][0]
                    col=colmap[(mr-r0, mc-c0)]
                    if trace: print('L at',(r,c),'box',(r0,c0),'missing',(mr,mc),'col',col)
                    for rr,cc in cells: used[rr][cc]=True; out[rr][cc]=col
                    done=True; break
            if trace and not done: print('stuck at',(r,c))
    return out

