def tilings(grid):
    h=len(grid); w=len(grid[0])
    cells=[(r,c) for r in range(h) for c in range(w) if grid[r][c]==8]
    S=set(cells)
    pieces=[]
    for r in range(h-1):
        for c in range(w-1):
            box=[(r+dr,c+dc) for dr in(0,1) for dc in(0,1)]
            if all(x in S for x in box): pieces.append(('2x2',frozenset(box)))
            for m in box:
                L=frozenset(x for x in box if x!=m)
                if L<=S: pieces.append((('miss',(m[0]-r,m[1]-c)),L))
    # exact cover
    res=[]
    def rec(rem, cur):
        if not rem: res.append(cur); return
        first=min(rem)
        for typ,P in pieces:
            if first in P and P<=rem:
                rec(rem-P, cur+[('miss' if typ[0]=='miss' else typ, typ[1] if typ[0]=='miss' else None, P)])
    rec(frozenset(S),[])
    return res
