def transform(grid):
    h=len(grid); w=len(grid[0])
    S=frozenset((r,c) for r in range(h) for c in range(w) if grid[r][c]==8)
    out=[row[:] for row in grid]
    colmap={(0,0):2,(1,0):3,(0,1):4,(1,1):5}
    pieces=[]
    for r in range(h-1):
        for c in range(w-1):
            box=[(r+dr,c+dc) for dr in(0,1) for dc in(0,1)]
            if all(x in S for x in box): pieces.append((1,None,frozenset(box)))
            for m in box:
                L=frozenset(x for x in box if x!=m)
                if L<=S: pieces.append((colmap[(m[0]-r,m[1]-c)],None,L))
    def rec(rem,acc):
        if not rem: return acc
        first=min(rem)
        for col,_,P in pieces:
            if first in P and P<=rem:
                r=rec(rem-P,acc+[(col,P)])
                if r is not None: return r
        return None
    for col,P in rec(S,[]):
        for rr,cc in P: out[rr][cc]=col
    return out

